package com.bank.phonebook.service;

import com.bank.phonebook.model.Employee;
import java.util.Comparator;
import java.util.List;
import java.util.logging.Logger;
import java.util.stream.Collectors;

public class PhoneBookService {
    private static final Logger log = Logger.getLogger(PhoneBookService.class.getName());

    public List<Employee> byNameCaseInsensitive(List<Employee> employees) {
        log.info(() -> "Sorting " + employees.size() + " names alphabetically (case-insensitive)");
        return employees.stream()
                // Key = name; key comparator ignores case → natural A–Z.
                .sorted(Comparator.comparing(Employee::getName, String.CASE_INSENSITIVE_ORDER))
                .collect(Collectors.toList());
    }
}
