package com.bank.phonebook;

import com.bank.phonebook.model.Employee;
import com.bank.phonebook.service.PhoneBookService;
import java.util.List;
import java.util.logging.Logger;

public class Main {
    private static final Logger log = Logger.getLogger(Main.class.getName());

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("rajesh"),   // lowercase
            new Employee("Priya"),
            new Employee("AMIT"),     // uppercase
            new Employee("neha")
        );

        new PhoneBookService().byNameCaseInsensitive(staff)
            .forEach(e -> log.info(() -> "Phone book: " + e));
    }
}
